mapper.select:
select * from ( select row_number() over (order by allowg_id) as rn , allowg_id, allowg_name from (select distinct allowg_id, allowg_name from allow_grade) as distinct_allowg
where allowg_name like concat('%',#{searchWord},'%')
) as sub where rn between #{startRow} and #{endRow}

mapper.update:
update allow_grade 
set allowg_name=#{allowgName}
, grade_id=#{gradeId}
where allowg_id=#{allowgId}

mapper.select:
select * from (
select row_number() over (order by grade_id) as rn
, grade_id, grade_name, grade_level
from grade

where
grade_name like concat('%',#{dto.searchWord},'%')

) as sub 

where rn 
between #{dto.startRow} and #{dto.endRow}


where grade_level >= #{gradeLevel}

mapper.update:
update grade
set grade_name = #{gradeName}
, grade_level = #{gradeLevel}
where grade_id = #{gradeId}
